/* From Uiverse.io by KhelVers - Tags: form, login form, log in, 3d form , 3d login form, standard, luxary */
.__UIV_SCOPE__ .login-container {
  width: 300px;
  padding: 20px;
  background: #fff;
  border-radius: 8px;
  box-shadow: 0px 10px 20px rgba(0, 0, 0, 0.1), 0px 0px 0px 3px #3498db, inset 0px 0px 10px rgba(0, 0, 0, 0.1);
}

.__UIV_SCOPE__ .login-header {
  font-size: x-large;
  font-weight: 600;
  text-align: center;
  margin-bottom: 20px;
}

.__UIV_SCOPE__ .login-header h1 {
  color: #333;
  font-size: 24px;
}

.__UIV_SCOPE__ .login-input {
  width: 100%;
  padding: 10px;
  margin-bottom: 15px;
  border: none;
  background: #f5f5f5;
  border-radius: 4px;
  box-shadow: inset 0px 1px 3px rgba(0, 0, 0, 0.2);
}

.__UIV_SCOPE__ .login-button {
  width: 100%;
  padding: 10px;
  border: none;
  background: #3498db;
  color: #fff;
  font-weight: bold;
  border-radius: 4px;
  cursor: pointer;
  box-shadow: 0px 3px 6px rgba(0, 0, 0, 0.1), inset 0px 1px 3px rgba(255, 255, 255, 0.5);
  transition: background 0.3s ease, transform 0.2s ease;
}

.__UIV_SCOPE__ .login-button:hover {
  background: #2980b9;
  transform: translateY(-2px);
}
